import [printf] from "std/c.bpl";

# Generic identity function - returns what it receives
frame identity<T>(val: T) ret T {
    return val;
}

# Generic swap function
frame swap<T>(a: *T, b: *T) {
    local temp: T = *a;
    *a = *b;
    *b = temp;
}

frame main() ret int {
    # Use identity with different types
    local num: int = identity<int>(42);
    printf("identity<int>(42) = %d\n", num);

    local pi: float = identity<float>(3.14);
    printf("identity<float>(3.14) = %.2f\n", pi);

    local flag: bool = identity<bool>(true);
    printf("identity<bool>(true) = %d\n", flag);

    # Generic swap
    local x: int = 10;
    local y: int = 20;
    printf("\nBefore swap: x=%d, y=%d\n", x, y);
    swap<int>(&x, &y);
    printf("After swap: x=%d, y=%d\n", x, y);

    local a: float = 1.5;
    local b: float = 2.5;
    printf("\nBefore swap: a=%.1f, b=%.1f\n", a, b);
    swap<float>(&a, &b);
    printf("After swap: a=%.1f, b=%.1f\n", a, b);

    return 0;
}

import [printf] from "std/c.bpl";

# Generic pair - holds two values of the same type
struct Pair<T> {
    first: T,
    second: T,
}

# Generic box - wraps a single value
struct Box<T> {
    value: T,

    frame get(this: *Box<T>) ret T {
        return this.value;
    }

    frame set(this: *Box<T>, newValue: T) {
        this.value = newValue;
    }
}

frame main() ret int {
    # Pair of ints
    local intPair: Pair<int> = Pair<int> {
        first: 10,
        second: 20
    };
    printf("Int pair: (%d, %d)\n", intPair.first, intPair.second);

    # Pair of floats
    local floatPair: Pair<float> = Pair<float> {
        first: 1.5,
        second: 2.5
    };
    printf("Float pair: (%.1f, %.1f)\n", floatPair.first, floatPair.second);

    # Box example
    local box: Box<int> = Box<int> { value: 42 };
    printf("\nBox contains: %d\n", box.get());

    box.set(100);
    printf("After set: %d\n", box.get());

    return 0;
}

import [printf] from "std/c.bpl";

# Two different types
struct KeyValue<K, V> {
    key: K,
    value: V,
}

# Either type - holds one of two possible types
enum Either<L, R> {
    Left(L),
    Right(R),
}

frame printEither(e: Either<int, string>) {
    match (e) {
        Either.Left(num) => printf("Left: %d\n", num),
        Either.Right(text) => printf("Right: %s\n", text),
    }
}

frame main() ret int {
    # KeyValue with different key/value types
    local kv1: KeyValue<string, int> = KeyValue<string, int> {
        key: "age",
        value: 25
    };
    printf("Key: %s, Value: %d\n", kv1.key, kv1.value);

    local kv2: KeyValue<int, float> = KeyValue<int, float> {
        key: 1,
        value: 3.14
    };
    printf("Key: %d, Value: %.2f\n", kv2.key, kv2.value);

    # Either type
    printf("\nEither examples:\n");
    local left: Either<int, string> = Either.Left(42);
    local right: Either<int, string> = Either.Right("hello");

    printEither(left);
    printEither(right);

    return 0;
}

import [printf] from "std/c.bpl";

# Simple generic stack (fixed size)
struct Stack<T> {
    data: T[100],  # Fixed-size array
    top: int,

    frame create() ret Stack<T> {
        local s: Stack<T>;
        s.top = 0;
        return s;
    }

    frame push(this: *Stack<T>, item: T) ret bool {
        if (this.top >= 100) {
            return false;  # Stack full
        }
        this.data[this.top] = item;
        this.top = this.top + 1;
        return true;
    }

    frame pop(this: *Stack<T>, out: *T) ret bool {
        if (this.top <= 0) {
            return false;  # Stack empty
        }
        this.top = this.top - 1;
        *out = this.data[this.top];
        return true;
    }

    frame isEmpty(this: *Stack<T>) ret bool {
        return this.top == 0;
    }

    frame size(this: *Stack<T>) ret int {
        return this.top;
    }
}

frame main() ret int {
    local intStack: Stack<int> = Stack<int>.create();

    # Push some values
    intStack.push(10);
    intStack.push(20);
    intStack.push(30);

    printf("Stack size: %d\n", intStack.size());

    # Pop and print
    local val: int;
    printf("Popping: ");
    loop (intStack.isEmpty() == false) {
        intStack.pop(&val);
        printf("%d ", val);
    }
    printf("\n");

    printf("Stack is empty: %d\n", intStack.isEmpty());

    return 0;
}

