import [printf] from "std/c.bpl";

struct MinMax<T> {
    min: T,
    max: T,
    count: int,

    frame init(first: T) ret MinMax<T> {
        return MinMax<T> {
            min: first,
            max: first,
            count: 1
        };
    }

    frame update(this: *MinMax<T>, val: T) {
        this.count = this.count + 1;
        if (val < this.min) {
            this.min = val;
        }
        if (val > this.max) {
            this.max = val;
        }
    }
}

frame main() ret int {
    local tracker: MinMax<int> = MinMax<int>.init(5);

    tracker.update(2);
    tracker.update(8);
    tracker.update(1);
    tracker.update(9);

    printf("Tracked %d values\n", tracker.count);
    printf("Min: %d\n", tracker.min);
    printf("Max: %d\n", tracker.max);

    return 0;
}
